/* Reliable Context Engineering Quiz
   Browser bundle for reliable Windows and GitHub Pages startup.
   Generated from the source modules; do not edit this file directly. */

/* ===== utils.js ===== */
function el(tag, attrs = {}, children = []) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    if (value === null || value === undefined) continue;
    if (key === "class") node.className = value;
    else if (key === "text") node.textContent = value;
    else if (key.startsWith("aria-")) node.setAttribute(key, value);
    else if (key === "dataset") Object.assign(node.dataset, value);
    else if (key in node && typeof value !== "object") node[key] = value;
    else node.setAttribute(key, value);
  }
  for (const child of Array.isArray(children) ? children : [children]) {
    if (child === null || child === undefined) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}
function clear(node){ node.replaceChildren(); }
function clamp(value,min,max){ return Math.min(Math.max(value,min),max); }
function announce(message){ const region=document.getElementById("status"); region.textContent=""; window.setTimeout(()=>{region.textContent=message;},20); }
function percent(numerator,denominator){ return denominator ? Math.round((numerator/denominator)*100) : 0; }

/* ===== scoring.js ===== */
function scoreAttempt(questions,answers){
  const details=questions.map(q=>{
    const selected=answers[q.id]??null;
    return {
      questionId:q.id,
      sourceNumber:q.sourceNumber,
      selectedChoiceId:selected,
      correctChoiceId:q.correctChoiceId,
      isCorrect:selected===q.correctChoiceId,
      isAnswered:selected!==null
    };
  });
  const correct=details.filter(d=>d.isCorrect).length;
  const answered=details.filter(d=>d.isAnswered).length;
  return {
    total:questions.length,
    answered,
    unanswered:questions.length-answered,
    correct,
    incorrect:answered-correct,
    percentage:questions.length?Math.round(correct/questions.length*100):0,
    details
  };
}

function createAttempt(questions,answers,{startedAt=null,contentVersion=null,now=new Date()}={}){
  const completedAt=now.toISOString();
  const startMs=startedAt?Date.parse(startedAt):NaN;
  const durationSeconds=Number.isFinite(startMs)?Math.max(0,Math.round((now.getTime()-startMs)/1000)):null;
  const score=scoreAttempt(questions,answers);
  return {
    id:`attempt-${now.getTime()}`,
    startedAt,
    completedAt,
    durationSeconds,
    questionIds:questions.map(q=>q.id),
    answers:{...answers},
    score,
    contentVersion
  };
}

/* ===== storage.js ===== */
const KEY="rceQuiz.progress";
const PREVIOUS_KEY="rceQuiz.progress.previous";
const TEMP_KEY="rceQuiz.progress.pending";
const STORAGE_VERSION=4;

let lastStatus={ok:true,available:true,recovered:false,message:"Progress storage is ready."};

function emptyProgress(){return {version:STORAGE_VERSION,chapters:{},updatedAt:null};}
function getStorageStatus(){return {...lastStatus};}

function setStatus(next){lastStatus={...lastStatus,...next};}

function normalizeScore(value={}){
  const total=Number.isInteger(value.total)?Math.max(0,value.total):0;
  const answered=Number.isInteger(value.answered)?Math.max(0,Math.min(total,value.answered)):0;
  const correct=Number.isInteger(value.correct)?Math.max(0,Math.min(answered,value.correct)):0;
  const unanswered=Number.isInteger(value.unanswered)?Math.max(0,Math.min(total,value.unanswered)):Math.max(0,total-answered);
  const incorrect=Number.isInteger(value.incorrect)?Math.max(0,Math.min(answered,value.incorrect)):Math.max(0,answered-correct);
  const percentage=Number.isFinite(value.percentage)?Math.max(0,Math.min(100,Math.round(value.percentage))):(total?Math.round(correct/total*100):0);
  return {total,answered,unanswered,correct,incorrect,percentage};
}

function normalizeAttempt(value={},index=0){
  if(!value||typeof value!=="object"||Array.isArray(value)) return null;
  const id=typeof value.id==="string"&&value.id?value.id:`migrated-${index+1}`;
  return {
    id,
    startedAt:typeof value.startedAt==="string"?value.startedAt:null,
    completedAt:typeof value.completedAt==="string"?value.completedAt:null,
    durationSeconds:Number.isFinite(value.durationSeconds)?Math.max(0,Math.round(value.durationSeconds)):null,
    questionIds:Array.isArray(value.questionIds)?value.questionIds.filter(id=>typeof id==="string"):[],
    answers:value.answers&&typeof value.answers==="object"&&!Array.isArray(value.answers)?{...value.answers}:{},
    score:normalizeScore(value.score),
    contentVersion:typeof value.contentVersion==="string"?value.contentVersion:null
  };
}

function normalizeDraft(value){
  if(!value||typeof value!=="object"||Array.isArray(value)) return null;
  return {
    chapterId:typeof value.chapterId==="string"?value.chapterId:null,
    questionIds:Array.isArray(value.questionIds)?value.questionIds.filter(id=>typeof id==="string"):[],
    answers:value.answers&&typeof value.answers==="object"&&!Array.isArray(value.answers)?{...value.answers}:{},
    index:Number.isInteger(value.index)?Math.max(0,value.index):0,
    startedAt:typeof value.startedAt==="string"?value.startedAt:null,
    updatedAt:typeof value.updatedAt==="string"?value.updatedAt:null
  };
}

function normalizeChapter(value={}){
  return {
    attempts:Array.isArray(value.attempts)?value.attempts.map(normalizeAttempt).filter(Boolean):[],
    draft:normalizeDraft(value.draft),
    legacyAttempts:Array.isArray(value.legacyAttempts)?value.legacyAttempts:[]
  };
}

function migrateProgress(parsed){
  if(!parsed||typeof parsed!=="object"||Array.isArray(parsed)) return emptyProgress();
  if([2,3,4].includes(parsed.version)&&parsed.chapters&&typeof parsed.chapters==="object"&&!Array.isArray(parsed.chapters)){
    const chapters=Object.fromEntries(Object.entries(parsed.chapters).map(([id,value])=>[id,normalizeChapter(value)]));
    return {...emptyProgress(),chapters,updatedAt:typeof parsed.updatedAt==="string"?parsed.updatedAt:null};
  }
  if(parsed.version===1&&parsed.chapters&&typeof parsed.chapters==="object"&&!Array.isArray(parsed.chapters)){
    const chapters=Object.fromEntries(Object.entries(parsed.chapters).map(([id,value])=>[id,{
      attempts:[],draft:null,legacyAttempts:Array.isArray(value?.attempts)?value.attempts:[]
    }]));
    return {...emptyProgress(),chapters,updatedAt:typeof parsed.updatedAt==="string"?parsed.updatedAt:null};
  }
  return emptyProgress();
}

function parseStored(raw){
  if(typeof raw!=="string"||!raw) return null;
  try{return migrateProgress(JSON.parse(raw));}catch{return null;}
}

function promoteCandidate(progress,sourceKey){
  const serialized=JSON.stringify(progress);
  try{
    localStorage.setItem(KEY,serialized);
    if(localStorage.getItem(KEY)!==serialized) throw new Error("Storage verification failed.");
    if(sourceKey!==KEY) localStorage.removeItem(sourceKey);
  }catch(error){console.warn("Recovered progress could not be promoted.",error);}
  return progress;
}

function readProgress(){
  try{
    const activeRaw=localStorage.getItem(KEY);
    const active=parseStored(activeRaw);
    if(active){
      setStatus({ok:true,available:true,recovered:false,message:"Progress storage is ready."});
      return active;
    }
    const previous=parseStored(localStorage.getItem(PREVIOUS_KEY));
    if(previous){
      setStatus({ok:true,available:true,recovered:true,message:"The last valid progress backup was restored after saved data became unreadable."});
      return promoteCandidate(previous,PREVIOUS_KEY);
    }
    const pending=parseStored(localStorage.getItem(TEMP_KEY));
    if(pending){
      setStatus({ok:true,available:true,recovered:true,message:"An interrupted save was recovered successfully."});
      return promoteCandidate(pending,TEMP_KEY);
    }
    if(activeRaw){
      setStatus({ok:false,available:true,recovered:false,message:"Saved progress was unreadable. The application started with an empty record; import a backup to restore prior work."});
    }else setStatus({ok:true,available:true,recovered:false,message:"Progress storage is ready."});
    return emptyProgress();
  }catch(error){
    console.warn("Browser storage is unavailable.",error);
    setStatus({ok:false,available:false,recovered:false,message:"This browser is not allowing local progress storage. Answers may be lost when the page closes; export is unavailable until storage access is restored."});
    return emptyProgress();
  }
}

function writeProgress(progress){
  const next={...migrateProgress(progress),version:STORAGE_VERSION,updatedAt:new Date().toISOString()};
  const serialized=JSON.stringify(next);
  let previousRaw=null;
  try{
    previousRaw=localStorage.getItem(KEY);
    localStorage.setItem(TEMP_KEY,serialized);
    if(localStorage.getItem(TEMP_KEY)!==serialized) throw new Error("Temporary save verification failed.");
    if(previousRaw) localStorage.setItem(PREVIOUS_KEY,previousRaw);
    localStorage.setItem(KEY,serialized);
    if(localStorage.getItem(KEY)!==serialized) throw new Error("Active save verification failed.");
    localStorage.removeItem(TEMP_KEY);
    setStatus({ok:true,available:true,recovered:false,message:"Progress saved on this device."});
    return next;
  }catch(error){
    console.warn("Progress could not be saved.",error);
    try{
      if(previousRaw) localStorage.setItem(KEY,previousRaw);
      localStorage.removeItem(TEMP_KEY);
    }catch(recoveryError){console.warn("The prior save could not be restored.",recoveryError);}
    setStatus({ok:false,available:true,recovered:false,message:"Progress could not be saved. The last valid local record was preserved; export a backup before continuing if possible."});
    return parseStored(previousRaw)??migrateProgress(progress);
  }
}

function replaceProgress(progress){return writeProgress(migrateProgress(progress));}

function clearProgress(){
  try{
    localStorage.removeItem(KEY);localStorage.removeItem(PREVIOUS_KEY);localStorage.removeItem(TEMP_KEY);
    setStatus({ok:true,available:true,recovered:false,message:"All local progress was cleared."});
    return emptyProgress();
  }catch(error){
    console.warn("Progress could not be cleared.",error);
    setStatus({ok:false,available:false,recovered:false,message:"The browser prevented progress from being cleared."});
    return readProgress();
  }
}

function getDraft(progress,chapterId){return progress.chapters?.[chapterId]?.draft??null;}

function getAttempt(progress,chapterId,attemptId){
  const attempts=progress.chapters?.[chapterId]?.attempts??[];
  if(!attemptId) return attempts.at(-1)??null;
  return attempts.find(attempt=>attempt.id===attemptId)??null;
}

function saveDraft(progress,chapterId,draft){
  const existing=normalizeChapter(progress.chapters?.[chapterId]);
  const chapter={...existing,draft:{...normalizeDraft(draft),updatedAt:new Date().toISOString()}};
  return writeProgress({...progress,chapters:{...progress.chapters,[chapterId]:chapter}});
}

function removeDraft(progress,chapterId){
  const existing=normalizeChapter(progress.chapters?.[chapterId]);
  const chapter={...existing,draft:null};
  return writeProgress({...progress,chapters:{...progress.chapters,[chapterId]:chapter}});
}

function saveAttempt(progress,chapterId,attempt){
  const existing=normalizeChapter(progress.chapters?.[chapterId]);
  const normalized=normalizeAttempt(attempt,existing.attempts.length);
  const attempts=existing.attempts.filter(item=>item.id!==normalized.id);
  const chapter={...existing,attempts:[...attempts,normalized],draft:null};
  return writeProgress({...progress,chapters:{...progress.chapters,[chapterId]:chapter}});
}

function deleteChapterHistory(progress,chapterId){
  const existing=normalizeChapter(progress.chapters?.[chapterId]);
  const chapter={...existing,attempts:[]};
  return writeProgress({...progress,chapters:{...progress.chapters,[chapterId]:chapter}});
}

/* ===== metrics.js ===== */
function bestAttempt(attempts){
  return attempts.reduce((best,attempt)=>{
    if(!best) return attempt;
    const score=attempt.score?.percentage??0;
    const bestScore=best.score?.percentage??0;
    if(score>bestScore) return attempt;
    if(score===bestScore&&(attempt.completedAt??"")>(best.completedAt??"")) return attempt;
    return best;
  },null);
}

function deriveChapterMetric(ch,progress){
  const record=progress.chapters?.[ch.id]??{};
  const attempts=Array.isArray(record.attempts)?record.attempts:[];
  const draft=record.draft??null;
  const latest=attempts.at(-1)??null;
  const previous=attempts.length>1?attempts.at(-2):null;
  const best=bestAttempt(attempts);
  const draftAnswered=draft?Object.keys(draft.answers??{}).length:0;
  const draftTotal=draft?.questionIds?.length??ch.examQuestionCount??0;
  const latestScore=latest?.score??null;
  return {
    chapterId:ch.id,
    available:ch.status==="available",
    attempts:attempts.length,
    attemptRecords:attempts,
    draft,
    inProgress:Boolean(draft),
    draftAnswered,
    draftTotal,
    draftCompletion:draftTotal?Math.round(draftAnswered/draftTotal*100):0,
    started:Boolean(draft)||attempts.length>0,
    completed:attempts.length>0,
    latestAttempt:latest,
    previousAttempt:previous,
    bestAttempt:best,
    latestScore:latestScore?.percentage??null,
    bestScore:best?.score?.percentage??null,
    scoreChange:latest&&previous?(latest.score?.percentage??0)-(previous.score?.percentage??0):null,
    latestCorrect:latestScore?.correct??0,
    latestIncorrect:latestScore?.incorrect??0,
    latestUnanswered:latestScore?.unanswered??0,
    latestAnswered:latestScore?.answered??0,
    latestTotal:latestScore?.total??0,
    completionPercentage:attempts.length?100:(draftTotal?Math.round(draftAnswered/draftTotal*100):0)
  };
}

function deriveMetrics(manifest,progress){
  const chapterMetrics=manifest.chapters.map(ch=>deriveChapterMetric(ch,progress));
  const chaptersStarted=chapterMetrics.filter(c=>c.started).length;
  const chaptersCompleted=chapterMetrics.filter(c=>c.completed).length;
  const activeChapters=chapterMetrics.filter(c=>c.available).length;
  const activeCompleted=chapterMetrics.filter(c=>c.available&&c.completed).length;
  const latestTotals=chapterMetrics.reduce((acc,c)=>({
    correct:acc.correct+c.latestCorrect,
    total:acc.total+c.latestTotal,
    answered:acc.answered+c.latestAnswered,
    incorrect:acc.incorrect+c.latestIncorrect,
    unanswered:acc.unanswered+c.latestUnanswered
  }),{correct:0,total:0,answered:0,incorrect:0,unanswered:0});
  const completed=chapterMetrics.filter(c=>c.latestScore!==null);
  const totalAttempts=chapterMetrics.reduce((sum,c)=>sum+c.attempts,0);
  return {
    chapterMetrics,
    chaptersStarted,
    chaptersCompleted,
    activeChapters,
    activeCompleted,
    totalAttempts,
    totalQuestionsCompleted:latestTotals.total,
    totalQuestionsAnswered:latestTotals.answered,
    totalCorrect:latestTotals.correct,
    totalIncorrect:latestTotals.incorrect,
    totalUnanswered:latestTotals.unanswered,
    overallPercentage:latestTotals.total?Math.round(latestTotals.correct/latestTotals.total*100):0,
    averageLatest:completed.length?Math.round(completed.reduce((sum,c)=>sum+c.latestScore,0)/completed.length):0,
    averageBest:completed.length?Math.round(completed.reduce((sum,c)=>sum+(c.bestScore??0),0)/completed.length):0,
    overallCompletion:Math.round(chaptersCompleted/manifest.chapters.length*100),
    activeCompletion:activeChapters?Math.round(activeCompleted/activeChapters*100):0
  };
}

/* ===== backup.js ===== */
const BACKUP_FORMAT="rce-quiz-progress-backup";
const BACKUP_SCHEMA_VERSION="1.0.0";
const MAX_IMPORT_BYTES=2*1024*1024;

function isObject(value){return Boolean(value)&&typeof value==="object"&&!Array.isArray(value);}
function validDate(value){return value===null||value===undefined||(typeof value==="string"&&!Number.isNaN(Date.parse(value)));}

function summarizeProgress(progress,manifest){
  const chapters=[];
  let drafts=0;let attempts=0;
  for(const chapter of manifest.chapters){
    const record=progress.chapters?.[chapter.id]??{};
    const count=Array.isArray(record.attempts)?record.attempts.length:0;
    const hasDraft=Boolean(record.draft);
    drafts+=hasDraft?1:0;attempts+=count;
    if(hasDraft||count) chapters.push({id:chapter.id,number:chapter.number,title:chapter.shortTitle,attempts:count,hasDraft});
  }
  return {chapters,drafts,attempts,chapterCount:chapters.length,lastUpdated:progress.updatedAt??null};
}

function createProgressBackup(progress,manifest,now=new Date()){
  const normalized=migrateProgress(progress);
  return {
    format:BACKUP_FORMAT,
    schemaVersion:BACKUP_SCHEMA_VERSION,
    appVersion:manifest.appVersion,
    storageVersion:STORAGE_VERSION,
    contentVersion:manifest.contentVersion,
    exportedAt:now.toISOString(),
    book:{id:manifest.book.id,title:manifest.book.title,edition:manifest.book.edition},
    summary:summarizeProgress(normalized,manifest),
    progress:normalized
  };
}

function serializeProgressBackup(progress,manifest,now=new Date()){
  return JSON.stringify(createProgressBackup(progress,manifest,now),null,2)+"\n";
}

function backupFilename(now=new Date()){
  const date=now.toISOString().slice(0,10);
  return `rce-quiz-progress_${date}.json`;
}

function validateImportFileMeta(file){
  if(!file) throw new Error("Choose a backup JSON file.");
  if(!Number.isFinite(file.size)||file.size<1) throw new Error("The selected file is empty.");
  if(file.size>MAX_IMPORT_BYTES) throw new Error("The selected file is too large. RCE Quiz backups must be 2 MB or smaller.");
  const name=String(file.name??"").toLowerCase();
  if(name&&!name.endsWith(".json")) throw new Error("Choose a .json backup file created by this application.");
}

function parseBackupText(text){
  if(typeof text!=="string"||!text.trim()) throw new Error("The selected backup file is empty.");
  try{return JSON.parse(text);}catch{throw new Error("The selected file is not valid JSON.");}
}


function validateRawProgressValues(rawProgress){
  if(rawProgress.version===1) return;
  for(const [chapterId,record] of Object.entries(rawProgress.chapters)){
    if(!isObject(record)) throw new Error(`The ${chapterId} progress record is invalid.`);
    if(record.attempts!==undefined&&!Array.isArray(record.attempts)) throw new Error(`The ${chapterId} attempt history is invalid.`);
    for(const attempt of record.attempts??[]){
      if(!isObject(attempt)||!isObject(attempt.score)) throw new Error(`An attempt in ${chapterId} is invalid.`);
      const score=attempt.score;
      for(const field of ["total","answered","correct"]){
        if(!Number.isInteger(score[field])||score[field]<0) throw new Error(`Attempt ${String(attempt.id)} has an invalid ${field} value.`);
      }
      if(score.answered>score.total||score.correct>score.answered) throw new Error(`Attempt ${String(attempt.id)} has an invalid correct value.`);
      if(score.unanswered!==undefined&&(!Number.isInteger(score.unanswered)||score.unanswered!==score.total-score.answered)) throw new Error(`Attempt ${String(attempt.id)} has an invalid unanswered value.`);
      if(score.incorrect!==undefined&&(!Number.isInteger(score.incorrect)||score.incorrect!==score.answered-score.correct)) throw new Error(`Attempt ${String(attempt.id)} has an invalid incorrect value.`);
      if(score.percentage!==undefined&&(!Number.isInteger(score.percentage)||score.percentage<0||score.percentage>100)) throw new Error(`Attempt ${String(attempt.id)} has an invalid percentage value.`);
    }
  }
}

function compareScore(expected,actual,attemptId){
  const fields=["total","answered","unanswered","correct","incorrect","percentage"];
  for(const field of fields){
    if(actual?.[field]!==expected[field]) throw new Error(`Attempt ${attemptId} has an invalid ${field} value.`);
  }
}

function validateProgressBackup(value,{manifest,questionSets}){
  if(!isObject(value)||value.format!==BACKUP_FORMAT) throw new Error("This is not an RCE Quiz progress backup.");
  if(value.schemaVersion!==BACKUP_SCHEMA_VERSION) throw new Error(`Backup schema ${String(value.schemaVersion)} is not supported.`);
  const legacyPreChapter1=value.contentVersion==="2026.08-r1";
  if(value.contentVersion!==manifest.contentVersion&&!legacyPreChapter1) throw new Error("The backup uses a different assessment-content version and cannot be imported safely.");
  if(!validDate(value.exportedAt)) throw new Error("The backup export date is invalid.");
  if(!isObject(value.progress)) throw new Error("The backup does not contain a progress record.");
  if(![1,2,3,4].includes(value.progress.version)) throw new Error(`Storage schema ${String(value.progress.version)} is not supported.`);
  if(![1,2,3,4].includes(value.storageVersion)||value.storageVersion!==value.progress.version) throw new Error("The backup storage-version metadata is invalid.");
  if(!isObject(value.progress.chapters)) throw new Error("The backup chapter data is invalid.");
  validateRawProgressValues(value.progress);

  const progress=migrateProgress(value.progress);
  if(legacyPreChapter1){
    const legacyCh1=progress.chapters?.ch1;
    if(legacyCh1?.draft||(Array.isArray(legacyCh1?.attempts)&&legacyCh1.attempts.length)) throw new Error("This legacy backup contains unexpected Chapter 1 progress and cannot be imported safely.");
  }
  const known=new Set(manifest.chapters.map(chapter=>chapter.id));
  const active=new Set(manifest.chapters.filter(chapter=>chapter.status==="available").map(chapter=>chapter.id));
  const seenAttemptIds=new Set();

  for(const [chapterId,record] of Object.entries(progress.chapters)){
    if(!known.has(chapterId)) throw new Error(`Unknown chapter ID ${chapterId} was found in the backup.`);
    const attempts=Array.isArray(record.attempts)?record.attempts:[];
    const draft=record.draft;
    if(!active.has(chapterId)&&(attempts.length||draft)) throw new Error(`Progress for unavailable chapter ${chapterId} cannot be imported.`);
    if(!active.has(chapterId)) continue;
    const data=questionSets[chapterId];
    if(!data) throw new Error(`Question data for ${chapterId} was not available for import validation.`);
    const questions=data.questions;
    const expectedIds=questions.map(question=>question.id);
    const allowed=new Map(questions.map(question=>[question.id,new Set(question.choices.map(choice=>choice.id))]));

    if(draft){
      if(draft.chapterId!==chapterId) throw new Error(`The unfinished ${chapterId} attempt has a mismatched chapter ID.`);
      if(draft.questionIds.length!==expectedIds.length||expectedIds.some((id,index)=>draft.questionIds[index]!==id)) throw new Error(`The unfinished ${chapterId} attempt does not match the current question bank.`);
      if(draft.index<0||draft.index>=expectedIds.length) throw new Error(`The unfinished ${chapterId} attempt has an invalid question position.`);
      if(!validDate(draft.startedAt)||!validDate(draft.updatedAt)) throw new Error(`The unfinished ${chapterId} attempt has an invalid date.`);
      for(const [questionId,choiceId] of Object.entries(draft.answers)){
        if(!allowed.get(questionId)?.has(choiceId)) throw new Error(`The unfinished ${chapterId} attempt contains an invalid answer.`);
      }
    }

    for(const attempt of attempts){
      if(seenAttemptIds.has(attempt.id)) throw new Error(`Duplicate attempt ID ${attempt.id} was found.`);
      seenAttemptIds.add(attempt.id);
      if(attempt.questionIds.length!==expectedIds.length||expectedIds.some((id,index)=>attempt.questionIds[index]!==id)) throw new Error(`Attempt ${attempt.id} does not match the current ${chapterId} question bank.`);
      if(!validDate(attempt.startedAt)||!validDate(attempt.completedAt)) throw new Error(`Attempt ${attempt.id} has an invalid date.`);
      if(attempt.contentVersion!==data.contentVersion) throw new Error(`Attempt ${attempt.id} uses an incompatible chapter-content version.`);
      for(const [questionId,choiceId] of Object.entries(attempt.answers)){
        if(!allowed.get(questionId)?.has(choiceId)) throw new Error(`Attempt ${attempt.id} contains an invalid answer.`);
      }
      compareScore(scoreAttempt(questions,attempt.answers),attempt.score,attempt.id);
    }
  }

  return {
    backup:value,
    progress,
    summary:summarizeProgress(progress,manifest),
    sourceAppVersion:typeof value.appVersion==="string"?value.appVersion:"Unknown",
    exportedAt:value.exportedAt
  };
}

/* ===== data.js ===== */
const REQUIRED_CHOICE_IDS=["A","B","C","D"];
// Embedded at build time so the dashboard does not wait for a second startup request.
const APP_MANIFEST={"schemaVersion":"1.1.0","appVersion":"0.6.1-rc.3","book":{"id":"rce","title":"Reliable Generative AI Context Engineering","subtitle":"A Practical Guide to Context Engineering, Reliability, and Enterprise Operationalization","author":"George Tome","edition":"First edition, release 1 — August 2026","sourceFile":"Reliable Generative AI Context Engineering(3).pdf","totalSourceQuestions":120,"totalBlockedQuestions":0,"totalVerifiedQuestions":120,"activeExamQuestions":120,"activeExamChapters":5},"chapters":[{"id":"ch1","number":1,"title":"Foundations of Context Engineering","shortTitle":"Foundations","assessmentHeading":"Chapter 1 Questions","sourceQuestionPages":[33,37],"sourceRationalePages":[38,42],"sourceQuestionCount":30,"verifiedQuestionCount":30,"blockedQuestionCount":0,"examQuestionCount":30,"numbering":"1–30","status":"available","data":"./data/ch1.json","bankData":"./data/ch1.json","bankStatus":"verified","accent":"blue"},{"id":"ch2","number":2,"title":"The Context Engineering Lifecycle","shortTitle":"Lifecycle","assessmentHeading":"Assessment: Chapter 2 Questions","sourceQuestionPages":[69,71],"sourceRationalePages":[72,73],"sourceQuestionCount":15,"verifiedQuestionCount":15,"blockedQuestionCount":0,"examQuestionCount":15,"numbering":"31–45","status":"available","data":"./data/ch2.json","bankData":"./data/ch2.json","bankStatus":"verified","accent":"cyan"},{"id":"ch3","number":3,"title":"Designing High-Quality Contexts","shortTitle":"Context Quality","assessmentHeading":"Assessment: Chapter 3 Questions","sourceQuestionPages":[115,118],"sourceRationalePages":[119,122],"sourceQuestionCount":30,"verifiedQuestionCount":30,"blockedQuestionCount":0,"examQuestionCount":30,"numbering":"46–60 and 76–90","status":"available","data":"./data/ch3.json","bankData":"./data/ch3.json","bankStatus":"verified","accent":"teal","userNote":"Question numbers follow the book exactly. Chapter 3 contains Questions 46–60 and 76–90; Chapter 4 contains Questions 61–75 and 91–105. No questions are missing—the numbering is interleaved in the source book."},{"id":"ch4","number":4,"title":"Reliability, Failure Handling, and Measurement","shortTitle":"Reliability","assessmentHeading":"Chapter 4 Quiz","sourceQuestionPages":[162,166],"sourceRationalePages":[167,169],"sourceQuestionCount":30,"verifiedQuestionCount":30,"blockedQuestionCount":0,"examQuestionCount":30,"numbering":"61–75 and 91–105","status":"available","data":"./data/ch4.json","bankData":"./data/ch4.json","bankStatus":"verified","accent":"green","userNote":"Question numbers follow the book exactly. Chapter 3 contains Questions 46–60 and 76–90; Chapter 4 contains Questions 61–75 and 91–105. No questions are missing—the numbering is interleaved in the source book."},{"id":"ch5","number":5,"title":"Enterprise Operationalization","shortTitle":"Enterprise","assessmentHeading":"Chapter 5 Questions","sourceQuestionPages":[210,212],"sourceRationalePages":[213,215],"sourceQuestionCount":15,"verifiedQuestionCount":15,"blockedQuestionCount":0,"examQuestionCount":15,"numbering":"106–120","status":"available","data":"./data/ch5.json","bankData":"./data/ch5.json","bankStatus":"verified","accent":"navy"}],"contentVersion":"2026.08-r2"};
async function loadManifest(){validateManifest(APP_MANIFEST);return deepFreeze(APP_MANIFEST);}
async function loadChapter(path){return fetchJson(path,validatePlayableQuestionSet);}
async function fetchJson(path,validator){
  const response=await fetch(path,{cache:"default"});
  if(!response.ok) throw new Error(`Could not load ${path} (${response.status}).`);
  const value=await response.json();validator(value);return deepFreeze(value);
}
function validateManifest(data){
  if(!data||data.schemaVersion!=="1.1.0"||data.appVersion!=="0.6.1-rc.3"||data.contentVersion!=="2026.08-r2"||!Array.isArray(data.chapters)||data.chapters.length!==5) throw new Error("The chapter manifest is missing or invalid.");
  const ids=new Set(data.chapters.map(c=>c.id));if(ids.size!==5) throw new Error("Chapter IDs must be unique.");
  const active=data.chapters.filter(c=>c.status==="available");
  if(active.length!==5||active.some(c=>!c.data||c.examQuestionCount<1)) throw new Error("All five chapter exams must be active and complete.");
  if(data.book?.activeExamQuestions!==120||data.book?.totalVerifiedQuestions!==120||data.book?.totalBlockedQuestions!==0) throw new Error("The assessment totals are invalid.");
}
function validateQuestionBank(data){
  if(!data||data.schemaVersion!=="1.1.0"||!Array.isArray(data.questions)) throw new Error("Question data is missing or invalid.");
  const ids=new Set();
  for(const q of data.questions){
    if(!q.id||ids.has(q.id)) throw new Error("Question IDs must be present and unique.");ids.add(q.id);
    if(q.verificationStatus!=="verified") throw new Error(`Question ${q.id} is not approved for use.`);
    if(!q.availableForExam) throw new Error(`Verified question ${q.id} must be available.`);
    const choiceIds=q.choices?.map(c=>c.id);
    if(!Array.isArray(choiceIds)||choiceIds.length!==4||REQUIRED_CHOICE_IDS.some(id=>!choiceIds.includes(id))) throw new Error(`Question ${q.id} must have choices A-D.`);
    if(!choiceIds.includes(q.correctChoiceId)) throw new Error(`Question ${q.id} has an invalid correct answer.`);
  }
}
function validatePlayableQuestionSet(data){
  validateQuestionBank(data);
  const blocked=data.questions.filter(q=>!q.availableForExam||q.verificationStatus!=="verified");
  if(blocked.length) throw new Error(`This assessment contains ${blocked.length} question(s) that are not approved for use.`);
  if(data.chapter?.availableQuestionCount!==data.questions.length) throw new Error("The playable question count does not match the chapter metadata.");
}
function deepFreeze(value){if(value&&typeof value==="object"&&!Object.isFrozen(value)){Object.freeze(value);Object.values(value).forEach(deepFreeze);}return value;}

/* ===== state.js ===== */
function initialState(manifest,progress,{notice=null}={}){
  return {manifest,progress,route:{name:"home"},chapterData:null,quiz:null,reviewFilter:"all",importPreview:null,backupMessage:null,notice,error:null};
}

function reduce(state,action){
  switch(action.type){
    case "NAVIGATE": return {...state,route:action.route,reviewFilter:action.route.name==="results"?state.reviewFilter:"all",error:null};
    case "CHAPTER_LOADED": return {...state,chapterData:action.data,error:null};
    case "START_QUIZ": return {...state,reviewFilter:"all",quiz:{
      chapterId:action.chapterId,index:action.index??0,answers:{...(action.answers??{})},startedAt:action.startedAt??new Date().toISOString(),submitted:false,result:null,attempt:null,resumed:Boolean(action.resumed)
    }};
    case "ANSWER": return {...state,quiz:{...state.quiz,answers:{...state.quiz.answers,[action.questionId]:action.choiceId}}};
    case "GO_TO_QUESTION": return {...state,quiz:{...state.quiz,index:action.index}};
    case "SUBMIT_QUIZ": return {...state,reviewFilter:"all",quiz:{...state.quiz,submitted:true,result:action.result,attempt:action.attempt}};
    case "RESTORE_RESULT": return {...state,reviewFilter:"all",quiz:{chapterId:action.chapterId,index:0,answers:{...action.attempt.answers},startedAt:action.attempt.startedAt??null,submitted:true,result:action.result,attempt:action.attempt,resumed:false}};
    case "SET_REVIEW_FILTER": return {...state,reviewFilter:action.filter};
    case "PROGRESS_UPDATED": return {...state,progress:action.progress};
    case "IMPORT_PREVIEW": return {...state,importPreview:action.preview,backupMessage:action.message??null};
    case "BACKUP_MESSAGE": return {...state,backupMessage:action.message,importPreview:action.clearPreview?null:state.importPreview};
    case "NOTICE": return {...state,notice:action.notice};
    case "DISMISS_NOTICE": return {...state,notice:null};
    case "CLEAR_QUIZ": return {...state,quiz:null,reviewFilter:"all"};
    case "RESET": return {...state,progress:action.progress,quiz:null,reviewFilter:"all",importPreview:null};
    case "ERROR": return {...state,error:action.error};
    default:return state;
  }
}

/* ===== router.js ===== */
function parseRoute(hash=location.hash){
  const path=(hash.replace(/^#/,"")||"/").split("?")[0];
  const parts=path.split("/").filter(Boolean).map(part=>decodeURIComponent(part));
  if(parts.length===0) return {name:"home"};
  if(parts[0]==="help") return {name:"help"};
  if(parts[0]==="about") return {name:"about"};
  if(parts[0]==="backup") return {name:"backup"};
  if(parts[0]==="chapter" && /^ch[1-5]$/.test(parts[1]||"")) return {name:"chapter",chapterId:parts[1]};
  if(parts[0]==="quiz" && /^ch[1-5]$/.test(parts[1]||"")) return {name:"quiz",chapterId:parts[1]};
  if(parts[0]==="results" && /^ch[1-5]$/.test(parts[1]||"")) return {name:"results",chapterId:parts[1],attemptId:parts[2]||null};
  return {name:"notFound"};
}
function startRouter(onChange){window.addEventListener("hashchange",()=>onChange(parseRoute()));onChange(parseRoute());}

/* ===== dialog.js ===== */
let returnTarget=null;

function confirmAction({title,message,confirmLabel="Confirm",destructive=false}){
  const dialog=document.getElementById("confirm-dialog");
  const cancelButton=document.getElementById("dialog-cancel");
  const confirmButton=document.getElementById("dialog-confirm");
  returnTarget=document.activeElement instanceof HTMLElement?document.activeElement:null;
  document.getElementById("dialog-title").textContent=title;
  document.getElementById("dialog-message").textContent=message;
  confirmButton.textContent=confirmLabel;
  confirmButton.className=`button ${destructive?"button-danger-solid":"button-primary"}`;
  dialog.dataset.destructive=String(destructive);
  if(dialog.open) dialog.close("cancel");
  const containFocus=event=>{
    if(event.key!=="Tab") return;
    const focusables=[cancelButton,confirmButton].filter(button=>!button.disabled);
    const first=focusables[0];
    const last=focusables.at(-1);
    if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
    else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
    else if(!dialog.contains(document.activeElement)){event.preventDefault();first.focus();}
  };
  dialog.addEventListener("keydown",containFocus);
  dialog.showModal();
  window.requestAnimationFrame(()=>cancelButton.focus());
  return new Promise(resolve=>{
    dialog.addEventListener("close",()=>{
      dialog.removeEventListener("keydown",containFocus);
      const confirmed=dialog.returnValue==="confirm";
      const target=returnTarget?.isConnected?returnTarget:document.querySelector("#app h1, #main");
      window.requestAnimationFrame(()=>target?.focus({preventScroll:true}));
      resolve(confirmed);
    },{once:true});
  });
}

/* ===== render.js ===== */
function renderApp(root,state,actions){
  clear(root);
  if(state.error){
    root.append(el("div",{class:"error",role:"alert"},[
      el("h1",{tabindex:"-1",text:"The application could not continue"}),
      el("p",{text:state.error.message||String(state.error)}),
      el("a",{href:"#/",class:"button button-secondary",text:"Return to dashboard"})
    ]));
    return;
  }
  if(state.notice){
    root.append(el("div",{class:`system-notice ${state.notice.type||"info"}`,role:state.notice.type==="error"?"alert":"status"},[
      el("div",{},[el("strong",{text:state.notice.type==="error"?"Storage warning":"Recovery notice"}),el("p",{text:state.notice.text})]),
      el("button",{class:"button button-quiet",type:"button",text:"Dismiss",onclick:actions.dismissNotice})
    ]));
  }
  const route=state.route;
  if(route.name==="home") root.append(renderHome(state));
  else if(route.name==="chapter") root.append(renderChapter(state,actions));
  else if(route.name==="quiz") root.append(renderQuiz(state,actions));
  else if(route.name==="results") root.append(renderResults(state,actions));
  else if(route.name==="backup") root.append(renderBackup(state,actions));
  else if(route.name==="help") root.append(renderHelp(state,actions));
  else if(route.name==="about") root.append(renderAbout(state));
  else root.append(el("section",{class:"panel"},[
    el("h1",{tabindex:"-1",text:"Page not found"}),
    el("p",{text:"The requested view does not exist."}),
    el("a",{href:"#/",class:"button button-primary",text:"Go to dashboard"})
  ]));
}

function renderHome(state){
  const m=deriveMetrics(state.manifest,state.progress);
  const section=el("div");
  section.append(el("section",{class:"hero"},[
    el("div",{},[
      el("p",{class:"eyebrow",text:"Reliable Generative AI Context Engineering"}),
      el("h1",{tabindex:"-1",text:"Practice reliable AI judgment—one chapter at a time."}),
      el("p",{class:"hero-copy",text:"A mobile-first assessment companion with complete exams for all five chapters, detailed rationales, attempt history, and progress metrics designed for focused study on a phone."})
    ]),
    el("div",{class:"hero-visual","aria-hidden":"true"},[el("img",{src:"./assets/mark.svg",alt:""})])
  ]));

  section.append(el("div",{class:"section-head"},[
    el("div",{},[el("p",{class:"eyebrow",text:"Progress dashboard"}),el("h2",{text:"Your local learning record"})]),
    el("p",{text:"Latest completed attempts are used for the primary book score."})
  ]));
  section.append(el("section",{class:"metrics metrics-expanded","aria-label":"Overall progress metrics"},[
    metric(`${m.chaptersStarted} / 5`,"Chapters started"),
    metric(`${m.chaptersCompleted} / 5`,"Chapters completed"),
    metric(`${m.overallPercentage}%`,"Question-weighted latest score"),
    metric(`${m.averageBest}%`,"Average best chapter score"),
    metric(String(m.totalCorrect),"Correct in latest attempts"),
    metric(String(m.totalQuestionsCompleted),"Questions in latest attempts"),
    metric(String(m.totalAttempts),"Completed attempts"),
    metric(`${m.overallCompletion}%`,"Whole-book completion")
  ]));
  section.append(el("details",{class:"metric-method"},[
    el("summary",{text:"How these progress metrics are calculated"}),
    el("div",{},[
      el("p",{text:"The question-weighted score adds the correct answers from each chapter's latest completed attempt and divides by the total questions in those attempts. It does not average chapter percentages."}),
      el("p",{text:"Average best score is a separate chapter-level metric. Whole-book completion uses all five active chapter exams."})
    ])
  ]));

  section.append(el("div",{class:"section-head"},[
    el("div",{},[el("p",{class:"eyebrow",text:"Five-part journey"}),el("h2",{text:"Chapter assessments"})]),
    el("p",{text:"Start, resume, review, or retake a chapter."})
  ]));
  const grid=el("section",{class:"chapter-grid","aria-label":"Chapter assessments"});
  for(const ch of state.manifest.chapters){
    const cm=m.chapterMetrics.find(item=>item.chapterId===ch.id);
    const unavailable=ch.status!=="available";
    let statusText="Exam available";
    let pillClass="available";
    let actionText="Open chapter";
    if(unavailable){
      statusText="Exam unavailable";pillClass="unavailable";actionText="View chapter status";
    }else if(cm.inProgress){
      statusText=`In progress · ${cm.draftAnswered} of ${cm.draftTotal} answered`;pillClass="in-progress";actionText="Resume exam";
    }else if(cm.completed){
      statusText=`Latest ${cm.latestScore}% · Best ${cm.bestScore}%`;pillClass="completed";actionText="View progress";
    }
    const details=[];
    if(cm.completed) details.push(el("p",{class:"chapter-progress-line",text:`${cm.attempts} completed attempt${cm.attempts===1?"":"s"} · ${cm.latestCorrect}/${cm.latestTotal} correct latest`}));
    const card=el("article",{class:`chapter-card accent-${ch.accent}`},[
      el("div",{class:"chapter-number",text:String(ch.number)}),
      el("h3",{text:ch.title}),
      el("p",{class:"chapter-meta",text:`${ch.sourceQuestionCount} source questions · ${ch.numbering}`}),
      ch.userNote?el("p",{class:"chapter-note",text:"Numbering follows the source book; no questions are missing."}):null,
      ...details,
      el("div",{class:"status"},[
        el("span",{class:`status-pill ${pillClass}`,text:statusText}),
        el("a",{href:`#/chapter/${ch.id}`,class:"button button-secondary card-action",text:actionText})
      ])
    ]);
    grid.append(card);
  }
  section.append(grid);
  return section;
}

function metric(value,label){return el("div",{class:"metric"},[el("strong",{text:value}),el("span",{text:label})]);}

function renderChapter(state,actions){
  const ch=state.manifest.chapters.find(c=>c.id===state.route.chapterId);
  if(!ch) return el("div",{class:"error",text:"Chapter not found."});
  const cm=deriveChapterMetric(ch,state.progress);
  const draft=cm.draft;
  const latest=cm.latestAttempt;
  const available=ch.status==="available";
  const body=[
    breadcrumbs(ch),
    el("section",{class:"panel"},[
      el("div",{class:"chapter-hero"},[
        el("div",{},[
          el("p",{class:"eyebrow",text:`Chapter ${ch.number}`}),
          el("h1",{tabindex:"-1",text:ch.title}),
          el("p",{class:"hero-copy",text:available?`Take the complete ${ch.examQuestionCount}-question assessment using the verified question bank. In-progress answers and completed attempts are stored locally on this device.`:"This chapter is currently unavailable."})
        ]),
        el("div",{class:"chapter-badge",text:String(ch.number),"aria-hidden":"true"})
      ]),
      el("div",{class:"fact-list"},[
        fact("Source questions",String(ch.sourceQuestionCount)),
        fact("Exam questions",available?String(ch.examQuestionCount):"Pending"),
        fact("Completed attempts",String(cm.attempts)),
        fact("Numbering",ch.numbering)
      ]),
      el("div",{class:"notice"},[el("strong",{text:"Assessment heading: "}),ch.assessmentHeading]),
      ch.userNote?el("div",{class:"callout"},[
        el("h2",{text:"Question-numbering note"}),
        el("p",{text:ch.userNote})
      ]):null,
      available?renderChapterProgress(cm):null,
      available?renderExamInstructions(ch):el("div",{class:"unavailable-panel"},[
        el("h2",{text:"Not yet available"}),
        el("p",{text:"This chapter is not currently available."})
      ]),
      available?renderChapterActions(ch,draft,latest,actions):el("div",{class:"quiz-actions"},[
        el("button",{class:"button button-primary",disabled:true,text:"Exam unavailable"}),
        el("a",{class:"button button-quiet",href:"#/",text:"Back to dashboard"})
      ]),
      available&&cm.attempts?renderAttemptHistory(ch,cm):null,
      available&&(draft||cm.attempts)?renderManageProgress(ch,cm,actions):null
    ])
  ];
  return el("div",{},body);
}

function renderChapterProgress(cm){
  if(!cm.inProgress&&!cm.completed){
    return el("section",{class:"chapter-progress empty-progress","aria-labelledby":"chapter-progress-title"},[
      el("h2",{id:"chapter-progress-title",text:"Chapter progress"}),
      el("p",{text:"No attempt has been started. Your latest score, best score, and attempt history will appear here after you begin."})
    ]);
  }
  const change=cm.scoreChange===null?"First completed attempt":scoreChangeText(cm.scoreChange);
  return el("section",{class:"chapter-progress","aria-labelledby":"chapter-progress-title"},[
    el("div",{class:"section-head compact"},[
      el("div",{},[el("p",{class:"eyebrow",text:"Local chapter record"}),el("h2",{id:"chapter-progress-title",text:"Chapter progress"})]),
      cm.completed?el("p",{class:"score-change",text:change}):el("p",{text:"Unfinished attempt saved"})
    ]),
    el("div",{class:"chapter-metrics"},[
      metric(cm.latestScore===null?"—":`${cm.latestScore}%`,"Latest score"),
      metric(cm.bestScore===null?"—":`${cm.bestScore}%`,"Best score"),
      metric(String(cm.attempts),"Completed attempts"),
      metric(`${cm.completionPercentage}%`,"Chapter completion")
    ]),
    cm.completed?el("p",{class:"progress-detail",text:`Latest attempt: ${cm.latestCorrect} correct, ${cm.latestIncorrect} incorrect, and ${cm.latestUnanswered} unanswered out of ${cm.latestTotal}.`}):null,
    cm.inProgress?el("div",{class:"resume-summary",role:"status"},[
      el("strong",{text:"Unfinished attempt"}),
      el("span",{text:`${cm.draftAnswered} of ${cm.draftTotal} answered · ${cm.draftCompletion}% complete`})
    ]):null
  ]);
}

function renderExamInstructions(ch){
  return el("section",{class:"exam-instructions","aria-labelledby":"exam-instructions-title"},[
    el("h2",{id:"exam-instructions-title",text:"Before you begin"}),
    el("ul",{},[
      el("li",{text:`The exam contains ${ch.examQuestionCount} questions in the book's original order and numbering.`}),
      el("li",{text:"You can skip questions, use the question map, and return before submitting."}),
      el("li",{text:"Answers and your current position are saved automatically in this browser."}),
      el("li",{text:"Starting a retake never erases completed attempt history."}),
      el("li",{text:"Correct answers and official rationales remain hidden until you submit."}),
      el("li",{text:"This is a self-study assessment, not a proctored or tamper-resistant exam."})
    ])
  ]);
}

function renderChapterActions(ch,draft,latest,actions){
  const controls=[];
  if(draft){
    const answered=Object.keys(draft.answers??{}).length;
    controls.push(el("div",{class:"resume-summary",role:"status"},[
      el("strong",{text:"Exam in progress"}),
      el("span",{text:`${answered} of ${ch.examQuestionCount} answered · last position saved`})
    ]));
    controls.push(el("div",{class:"quiz-actions"},[
      el("button",{class:"button button-primary",type:"button",text:"Resume exam",onclick:()=>actions.resumeExam(ch.id)}),
      el("button",{class:"button button-secondary",type:"button",text:"Start over",onclick:()=>actions.startExam(ch.id)}),
      latest?el("a",{class:"button button-quiet",href:attemptHref(ch.id,latest.id),text:`Review latest result (${latest.score.percentage}%)`}):null
    ]));
  }else{
    controls.push(el("div",{class:"quiz-actions"},[
      el("button",{class:"button button-primary",type:"button",text:latest?"Retake chapter exam":"Start chapter exam",onclick:()=>actions.startExam(ch.id)}),
      latest?el("a",{class:"button button-secondary",href:attemptHref(ch.id,latest.id),text:`Review latest result (${latest.score.percentage}%)`}):el("a",{class:"button button-quiet",href:"#/",text:"Back to dashboard"})
    ]));
  }
  if(draft||latest) controls.push(el("a",{class:"text-link",href:"#/",text:"Return to dashboard"}));
  return el("div",{class:"chapter-actions"},controls);
}

function renderAttemptHistory(ch,cm){
  const list=el("ol",{class:"attempt-list"});
  const bestId=cm.bestAttempt?.id;
  cm.attemptRecords.map((attempt,index)=>({attempt,index})).reverse().forEach(({attempt,index})=>{
    const isBest=attempt.id===bestId;
    const isLatest=attempt.id===cm.latestAttempt?.id;
    list.append(el("li",{class:"attempt-item"},[
      el("div",{class:"attempt-main"},[
        el("div",{class:"attempt-title"},[
          el("strong",{text:`Attempt ${index+1}`}),
          isLatest?el("span",{class:"mini-pill latest",text:"Latest"}):null,
          isBest?el("span",{class:"mini-pill best",text:"Best"}):null
        ]),
        el("span",{class:"attempt-date",text:formatDate(attempt.completedAt)}),
        el("span",{class:"attempt-counts",text:`${attempt.score.correct}/${attempt.score.total} correct · ${attempt.score.unanswered} unanswered`})
      ]),
      el("div",{class:"attempt-score","aria-label":`Attempt ${index+1} score ${attempt.score.percentage} percent`},[
        el("strong",{text:`${attempt.score.percentage}%`}),
        el("a",{href:attemptHref(ch.id,attempt.id),class:"button button-secondary",text:"Review"})
      ])
    ]));
  });
  return el("section",{class:"attempt-history","aria-labelledby":"attempt-history-title"},[
    el("div",{class:"section-head compact"},[
      el("div",{},[el("p",{class:"eyebrow",text:"Saved locally"}),el("h2",{id:"attempt-history-title",text:"Attempt history"})]),
      el("p",{text:`${cm.attempts} completed attempt${cm.attempts===1?"":"s"}`})
    ]),
    list
  ]);
}

function renderManageProgress(ch,cm,actions){
  const controls=[];
  if(cm.inProgress) controls.push(el("button",{class:"button button-danger",type:"button",text:"Clear unfinished attempt",onclick:()=>actions.clearDraft(ch.id)}));
  if(cm.attempts) controls.push(el("button",{class:"button button-danger",type:"button",text:"Delete chapter history",onclick:()=>actions.deleteChapterHistory(ch.id)}));
  return el("details",{class:"manage-progress"},[
    el("summary",{text:"Manage saved chapter progress"}),
    el("div",{},[
      el("p",{text:"These controls affect only this browser and device. Clearing an unfinished attempt and deleting completed history are separate actions."}),
      el("div",{class:"quiz-actions manage-actions"},controls)
    ])
  ]);
}

function breadcrumbs(ch){
  return el("nav",{class:"breadcrumbs","aria-label":"Breadcrumb"},[
    el("a",{href:"#/",text:"Dashboard"}),
    el("span",{"aria-hidden":"true",text:"/"}),
    el("span",{text:`Chapter ${ch.number}`})
  ]);
}

function fact(label,value){return el("div",{class:"fact"},[el("strong",{text:value}),el("span",{text:label})]);}

function renderQuiz(state,actions){
  const data=state.chapterData;
  const quiz=state.quiz;
  if(!data||!quiz||quiz.chapterId!==data.chapter.id){
    return el("div",{class:"panel"},[el("h1",{tabindex:"-1",text:"Loading chapter exam…"}),el("p",{text:"The verified question data is being prepared."})]);
  }
  const chapter=state.manifest.chapters.find(c=>c.id===quiz.chapterId);
  const questions=data.questions;
  const q=questions[quiz.index];
  const answered=Object.keys(quiz.answers).length;
  const unanswered=questions.length-answered;
  const choices=el("fieldset",{class:"choice-list","aria-labelledby":"question-heading","aria-describedby":"question-help"},[
    el("legend",{class:"sr-only",text:`Select one answer for question ${q.sourceNumber}`})
  ]);
  for(const choice of q.choices){
    const input=el("input",{
      type:"radio",name:`answer-${q.id}`,value:choice.id,checked:quiz.answers[q.id]===choice.id,
      dataset:{questionId:q.id,choiceId:choice.id},onchange:()=>actions.answer(q.id,choice.id)
    });
    choices.append(el("label",{class:"choice"},[
      input,
      el("span",{},[el("span",{class:"choice-letter",text:`${choice.id}.`}),choice.text])
    ]));
  }
  const nav=el("div",{class:"q-nav","aria-label":"Question navigation"});
  questions.forEach((item,i)=>nav.append(el("button",{
    type:"button",
    class:`${i===quiz.index?"current ":""}${quiz.answers[item.id]?"answered":"unanswered"}`.trim(),
    text:String(item.sourceNumber),
    "aria-label":`Question ${item.sourceNumber}${quiz.answers[item.id]?", answered":", unanswered"}`,
    "aria-current":i===quiz.index?"step":null,
    "aria-controls":"question-heading",
    onclick:()=>actions.goTo(i)
  })));
  const previous=el("button",{class:"button button-quiet",type:"button",text:"Previous",disabled:quiz.index===0,onclick:()=>actions.goTo(quiz.index-1)});
  const next=quiz.index===questions.length-1?el("button",{class:"button button-primary",type:"button",text:"Review and submit",onclick:actions.submit}):el("button",{class:"button button-primary",type:"button",text:"Next question",onclick:()=>actions.goTo(quiz.index+1)});
  const map=el("aside",{class:"quiz-side","aria-label":"Chapter exam navigation"},[
    el("details",{class:"question-map",open:window.matchMedia("(min-width:52rem)").matches},[
      el("summary",{text:`Question map · ${answered}/${questions.length} answered`}),
      el("div",{},[
        el("h2",{text:`Chapter ${chapter.number} map`}),
        el("div",{class:"map-legend","aria-hidden":"true"},[
          el("span",{class:"legend-item"},[el("i",{class:"legend-swatch answered"}),"Answered"]),
          el("span",{class:"legend-item"},[el("i",{class:"legend-swatch current"}),"Current"])
        ]),
        nav,
        el("p",{class:"side-note",text:"Answers save automatically. Correct answers and rationales remain hidden until submission."}),
        el("button",{class:"button button-quiet card-action",type:"button",text:"Save and exit exam",onclick:actions.exitExam})
      ])
    ])
  ]);
  return el("div",{},[
    breadcrumbs(chapter),
    el("div",{class:"quiz-layout"},[
      el("section",{class:"quiz-main","aria-labelledby":"question-heading"},[
        el("div",{class:"progress-row"},[
          el("span",{text:`Question ${quiz.index+1} of ${questions.length}`}),
          el("span",{text:`${answered} answered · ${unanswered} remaining`})
        ]),
        el("progress",{class:"progress-native",value:quiz.index+1,max:questions.length,"aria-label":`Question position: ${quiz.index+1} of ${questions.length}`}),
        el("p",{class:"eyebrow",text:`Chapter ${chapter.number} · Source question ${q.sourceNumber}`}),
        el("h1",{id:"question-heading",class:"question-title",tabindex:"-1",text:q.prompt}),
        el("p",{id:"question-help",class:"question-help",text:"Choose one answer. Your selection is saved automatically on this device."}),
        choices,
        el("p",{class:"auto-save-note",role:"status",text:quiz.answers[q.id]?"Answer selected and saved on this device.":"No answer selected for this question yet."}),
        el("div",{class:"quiz-actions mobile-sticky-actions"},[previous,next])
      ]),
      map
    ])
  ]);
}

function renderResults(state,actions){
  const data=state.chapterData;
  const score=state.quiz?.result;
  const attempt=state.quiz?.attempt;
  const chapter=state.manifest.chapters.find(c=>c.id===state.route.chapterId);
  if(!data||!score||!attempt||!chapter){
    return el("section",{class:"panel"},[
      el("h1",{tabindex:"-1",text:"No completed result found"}),
      el("p",{text:"Complete the chapter exam before opening its results."}),
      el("a",{href:`#/chapter/${state.route.chapterId}`,class:"button button-primary",text:"Return to chapter"})
    ]);
  }
  const cm=deriveChapterMetric(chapter,state.progress);
  const attemptIndex=cm.attemptRecords.findIndex(item=>item.id===attempt.id);
  const previous=attemptIndex>0?cm.attemptRecords[attemptIndex-1]:null;
  const change=previous?score.percentage-(previous.score?.percentage??0):null;
  const isBest=cm.bestAttempt?.id===attempt.id;
  const filters=[
    {id:"all",label:"All",count:score.total},
    {id:"correct",label:"Correct",count:score.correct},
    {id:"incorrect",label:"Incorrect",count:score.incorrect},
    {id:"unanswered",label:"Unanswered",count:score.unanswered}
  ];
  const filtered=score.details.filter(detail=>{
    if(state.reviewFilter==="correct") return detail.isCorrect;
    if(state.reviewFilter==="incorrect") return detail.isAnswered&&!detail.isCorrect;
    if(state.reviewFilter==="unanswered") return !detail.isAnswered;
    return true;
  });
  const list=el("div",{class:"review-list",id:"review-list","aria-label":"Official answer review"});
  for(const detail of filtered){
    const q=data.questions.find(item=>item.id===detail.questionId);
    const chosen=q.choices.find(choice=>choice.id===detail.selectedChoiceId);
    const correct=q.choices.find(choice=>choice.id===q.correctChoiceId);
    const status=detail.isCorrect?"✓ Correct":detail.isAnswered?"✕ Incorrect":"— Unanswered";
    const statusClass=detail.isCorrect?"correct":detail.isAnswered?"incorrect":"unanswered";
    const reviewHeadingId=`review-${q.id}`;
    list.append(el("article",{class:`review-card ${statusClass}`,"aria-labelledby":reviewHeadingId},[
      el("div",{class:"review-card-head"},[
        el("h3",{id:reviewHeadingId,text:`Question ${q.sourceNumber}`}),
        el("span",{class:`review-status ${statusClass}`,text:status})
      ]),
      el("p",{class:"review-question",text:q.prompt}),
      el("div",{class:"answer-line"},[el("strong",{text:"Your answer: "}),chosen?`${chosen.id}. ${chosen.text}`:"No answer submitted"]),
      el("div",{class:"answer-line correct-answer"},[el("strong",{text:"Correct answer: "}),`${correct.id}. ${correct.text}`]),
      el("div",{class:"rationale"},[
        el("strong",{text:"Official rationale"}),
        el("p",{text:q.officialRationale}),
        el("small",{text:`Source: question page ${q.sourceQuestionPage}; rationale page ${q.sourceRationalePage}.`})
      ])
    ]));
  }
  if(!filtered.length){
    list.append(el("div",{class:"empty-filter",role:"status"},[
      el("h3",{text:"No questions match this filter"}),
      el("p",{text:"Choose another review filter to see the remaining questions."})
    ]));
  }
  const previousAttempt=attemptIndex>0?cm.attemptRecords[attemptIndex-1]:null;
  const nextAttempt=attemptIndex>=0&&attemptIndex<cm.attemptRecords.length-1?cm.attemptRecords[attemptIndex+1]:null;
  return el("div",{},[
    breadcrumbs(chapter),
    el("section",{class:"panel"},[
      el("p",{class:"eyebrow",text:`Chapter ${chapter.number} · Attempt ${attemptIndex+1} of ${cm.attempts}`}),
      el("h1",{tabindex:"-1",text:`${chapter.shortTitle} results`}),
      el("p",{class:"attempt-timestamp",text:`Completed ${formatDate(attempt.completedAt)}${attempt.durationSeconds!==null?` · ${formatDuration(attempt.durationSeconds)}`:""}`}),
      el("div",{class:"result-banner"},[
        el("div",{class:"score-ring","aria-label":`Score ${score.percentage} percent`},[el("span",{text:`${score.percentage}%`})]),
        el("div",{},[
          el("div",{class:"result-title-row"},[
            el("h2",{text:`${score.correct} of ${score.total} correct`}),
            isBest?el("span",{class:"mini-pill best",text:"Best attempt"}):null
          ]),
          el("p",{text:`${score.answered} answered · ${score.incorrect} incorrect · ${score.unanswered} unanswered`}),
          el("p",{class:"score-change",text:change===null?"First completed attempt":scoreChangeText(change)})
        ])
      ]),
      el("div",{class:"result-metrics","aria-label":"Attempt score details"},[
        metric(String(score.correct),"Correct"),
        metric(String(score.incorrect),"Incorrect"),
        metric(String(score.unanswered),"Unanswered"),
        metric(`${cm.bestScore}%`,"Chapter best")
      ]),
      el("div",{class:"attempt-nav","aria-label":"Attempt navigation"},[
        previousAttempt?el("a",{class:"button button-quiet",href:attemptHref(chapter.id,previousAttempt.id),text:"Previous attempt"}):el("span",{class:"button button-quiet disabled-link","aria-disabled":"true",text:"Previous attempt"}),
        el("a",{class:"button button-secondary",href:`#/chapter/${chapter.id}`,text:"Attempt history"}),
        nextAttempt?el("a",{class:"button button-quiet",href:attemptHref(chapter.id,nextAttempt.id),text:"Next attempt"}):el("span",{class:"button button-quiet disabled-link","aria-disabled":"true",text:"Next attempt"})
      ]),
      el("div",{class:"review-heading-row"},[
        el("div",{},[
          el("p",{class:"eyebrow",text:"Official answer review"}),
          el("h2",{id:"review-heading",tabindex:"-1",text:"Review each response"})
        ]),
        el("p",{class:"review-intro",id:"review-intro",text:"Filter the review without changing your saved result."})
      ]),
      el("div",{class:"review-filters",role:"group","aria-label":"Filter answer review","aria-describedby":"review-intro"},filters.map(filter=>el("button",{
        class:"filter-button",type:"button","aria-pressed":state.reviewFilter===filter.id,"aria-controls":"review-list",
        text:`${filter.label} (${filter.count})`,onclick:()=>actions.setReviewFilter(filter.id)
      }))),
      el("p",{class:"review-count",role:"status",text:`Showing ${filtered.length} of ${score.total} questions.`}),
      list,
      el("div",{class:"quiz-actions results-actions"},[
        el("button",{class:"button button-primary",type:"button",text:"Retake chapter exam",onclick:()=>actions.retake(chapter.id)}),
        el("a",{href:`#/chapter/${chapter.id}`,class:"button button-secondary",text:"Return to chapter"}),
        el("a",{href:"#/",class:"button button-quiet",text:"Dashboard"})
      ])
    ])
  ]);
}

function renderBackup(state,actions){
  const preview=state.importPreview;
  const message=state.backupMessage;
  const lastUpdated=state.progress.updatedAt?formatDate(state.progress.updatedAt):"No saved progress yet";
  const previewRows=preview?.summary.chapters.map(chapter=>el("li",{class:"backup-chapter-row"},[
    el("strong",{text:`Chapter ${chapter.number}: ${chapter.title}`}),
    el("span",{text:`${chapter.attempts} completed attempt${chapter.attempts===1?"":"s"}${chapter.hasDraft?" · unfinished attempt included":""}`})
  ]))??[];
  return el("div",{},[
    el("section",{class:"panel backup-page","aria-labelledby":"backup-heading"},[
      el("p",{class:"eyebrow",text:"v0.6.1-rc.3 · All five chapters"}),
      el("h1",{id:"backup-heading",tabindex:"-1",text:"Backup and restore progress"}),
      el("p",{class:"hero-copy",text:"Download a private JSON backup, move it to another phone or computer, or restore after browser data is cleared. Files are processed only in your browser and are never uploaded by this application."}),
      message?el("div",{class:`backup-message ${message.type}`,role:message.type==="error"?"alert":"status"},[
        el("strong",{text:message.type==="error"?"Backup issue":message.type==="success"?"Ready":"Backup status"}),
        el("p",{text:message.text})
      ]):null,
      el("section",{class:"version-panel","aria-labelledby":"version-heading"},[
        el("h2",{id:"version-heading",text:"Current versions"}),
        el("div",{class:"version-grid"},[
          fact("Application",`v${state.manifest.appVersion}`),
          fact("Storage schema",`v${state.progress.version}`),
          fact("Assessment content",state.manifest.contentVersion),
          fact("Last local update",lastUpdated)
        ])
      ]),
      el("section",{class:"backup-section","aria-labelledby":"export-heading"},[
        el("h2",{id:"export-heading",text:"1. Export a backup"}),
        el("p",{text:"The file includes unfinished answers, completed attempts, score history, and version metadata. It does not include account information because this application has no accounts."}),
        el("button",{class:"button button-primary",type:"button",text:"Download progress backup",onclick:actions.exportProgress}),
        el("p",{class:"privacy-note",text:"Treat the downloaded file as private learning-history data. Store it securely and delete copies you no longer need."})
      ]),
      el("section",{class:"backup-section","aria-labelledby":"import-heading"},[
        el("h2",{id:"import-heading",text:"2. Validate and restore a backup"}),
        el("p",{text:"Select a JSON backup created by RCE Quiz. Validation checks the schema, assessment version, chapter and question IDs, answer choices, duplicate attempts, dates, and score calculations before any local data is changed."}),
        el("div",{class:"file-control"},[
          el("label",{for:"backup-file",class:"file-label",text:"Choose progress backup (.json)"}),
          el("input",{id:"backup-file",name:"backup-file",type:"file",accept:"application/json,.json",onchange:event=>actions.chooseImport(event.target.files?.[0]??null)})
        ]),
        el("p",{class:"privacy-note",text:"Maximum file size: 2 MB. Invalid files are rejected without changing current progress."})
      ]),
      preview?el("section",{class:"import-preview","aria-labelledby":"import-preview-heading"},[
        el("p",{class:"eyebrow",text:"Validated backup"}),
        el("h2",{id:"import-preview-heading",tabindex:"-1",text:"Review before replacing progress"}),
        el("div",{class:"preview-metrics"},[
          metric(String(preview.summary.attempts),"Completed attempts"),
          metric(String(preview.summary.drafts),"Unfinished attempts"),
          metric(String(preview.summary.chapterCount),"Chapters with progress"),
          metric(preview.sourceAppVersion.startsWith("v")?preview.sourceAppVersion:`v${preview.sourceAppVersion}`,"Source app version")
        ]),
        el("p",{text:`Exported ${formatDate(preview.exportedAt)}. Importing replaces the entire progress record currently stored in this browser.`}),
        previewRows.length?el("ul",{class:"backup-chapter-list"},previewRows):el("p",{text:"This backup contains an empty progress record."}),
        el("div",{class:"backup-actions"},[
          el("button",{class:"button button-danger-solid",type:"button",text:"Import and replace local progress",onclick:actions.confirmImport}),
          el("button",{class:"button button-quiet",type:"button",text:"Cancel import",onclick:actions.cancelImport})
        ])
      ]):null,
      el("section",{class:"backup-section callout","aria-labelledby":"recovery-heading"},[
        el("h2",{id:"recovery-heading",text:"Automatic save protection"}),
        el("p",{text:"Before replacing a local progress record, the application writes and verifies a temporary copy and retains the prior valid record. If an interrupted or corrupted save is detected later, the application attempts recovery and reports what happened."})
      ])
    ])
  ]);
}

