function attemptHref(chapterId,attemptId){return `#/results/${chapterId}/${encodeURIComponent(attemptId)}`;}

function scoreChangeText(change){
  if(change===0) return "No change from the previous attempt";
  const direction=change>0?"higher":"lower";
  return `${Math.abs(change)} percentage point${Math.abs(change)===1?"":"s"} ${direction} than the previous attempt`;
}

function formatDate(value){
  if(!value) return "Date unavailable";
  const date=new Date(value);
  if(Number.isNaN(date.getTime())) return "Date unavailable";
  return new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short"}).format(date);
}

function formatDuration(seconds){
  if(!Number.isFinite(seconds)) return "Duration unavailable";
  const minutes=Math.floor(seconds/60);
  const remaining=seconds%60;
  if(minutes<1) return `${remaining} sec`;
  if(minutes<60) return `${minutes} min ${remaining} sec`;
  const hours=Math.floor(minutes/60);
  return `${hours} hr ${minutes%60} min`;
}

/* ===== app.js ===== */
const root=document.getElementById("app");
const baseTitle="Reliable Context Engineering Quiz";
let state;
let hasHandledInitialRoute=false;

function updateDocumentTitle(){
  const route=state?.route??{name:"home"};
  let prefix="Dashboard";
  if(route.name==="chapter") prefix=`Chapter ${chapterConfig(route.chapterId)?.number??""}`.trim();
  else if(route.name==="quiz") prefix=`Chapter ${chapterConfig(route.chapterId)?.number??""} exam`.trim();
  else if(route.name==="results") prefix=`Chapter ${chapterConfig(route.chapterId)?.number??""} results`.trim();
  else if(route.name==="backup") prefix="Backup and restore";
  else if(route.name==="help") prefix="Help";
  else if(route.name==="about") prefix="About";
  document.title=`${prefix} · ${baseTitle}`;
  document.body.dataset.route=route.name;
}


function dispatch(action,{renderNow=true,focusSelector=null,scrollToTop=false}={}){
  state=reduce(state,action);
  if(renderNow) render({focusSelector,scrollToTop});
}

function render({focusSelector=null,scrollToTop=false}={}){
  renderApp(root,state,actions);
  updateNav();
  updateDocumentTitle();
  window.requestAnimationFrame(()=>{
    if(scrollToTop) window.scrollTo({top:0,left:0,behavior:"auto"});
    const target=focusSelector?document.querySelector(focusSelector):null;
    if(target instanceof HTMLElement){
      target.focus({preventScroll:false});
      if(scrollToTop) target.scrollIntoView({block:"start",inline:"nearest",behavior:"auto"});
    }
  });
}

function updateNav(){
  document.querySelectorAll("#primary-nav a").forEach(anchor=>{
    const href=anchor.getAttribute("href");
    const isCurrent=(state.route.name==="home"&&href==="#/")||href===`#/${state.route.name}`;
    if(isCurrent) anchor.setAttribute("aria-current","page");
    else anchor.removeAttribute("aria-current");
  });
}

function chapterConfig(chapterId){return state.manifest.chapters.find(c=>c.id===chapterId)??null;}

function captureStorageNotice(){
  const status=getStorageStatus();
  if(!status.ok||status.recovered){
    dispatch({type:"NOTICE",notice:{type:status.ok?"warning":"error",text:status.message}},{renderNow:false});
  }
  return status;
}

async function loadActiveQuestionSets(){
  const entries=await Promise.all(state.manifest.chapters.filter(chapter=>chapter.status==="available"&&chapter.data).map(async chapter=>[chapter.id,await loadChapter(chapter.data)]));
  return Object.fromEntries(entries);
}

function downloadText(filename,text){
  const blob=new Blob([text],{type:"application/json;charset=utf-8"});
  const url=URL.createObjectURL(blob);
  const anchor=document.createElement("a");
  anchor.href=url;anchor.download=filename;anchor.hidden=true;
  document.body.append(anchor);anchor.click();anchor.remove();
  window.setTimeout(()=>URL.revokeObjectURL(url),1000);
}

async function ensureChapter(chapterId){
  const ch=chapterConfig(chapterId);
  if(!ch?.data||ch.status!=="available") return null;
  if(state.chapterData?.chapter.id===chapterId) return state.chapterData;
  const data=await loadChapter(ch.data);
  if(data.chapter.id!==chapterId) throw new Error("The loaded chapter does not match the requested exam.");
  dispatch({type:"CHAPTER_LOADED",data},{renderNow:false});
  return data;
}

function compatibleDraft(data,draft){
  if(!draft||draft.chapterId!==data.chapter.id||!Array.isArray(draft.questionIds)) return null;
  const expected=data.questions.map(q=>q.id);
  if(expected.length!==draft.questionIds.length||expected.some((id,i)=>id!==draft.questionIds[i])) return null;
  const allowed=new Map(data.questions.map(q=>[q.id,new Set(q.choices.map(c=>c.id))]));
  const answers=Object.fromEntries(Object.entries(draft.answers??{}).filter(([questionId,choiceId])=>allowed.get(questionId)?.has(choiceId)));
  return {
    chapterId:data.chapter.id,
    index:clamp(Number.isInteger(draft.index)?draft.index:0,0,data.questions.length-1),
    answers,
    startedAt:draft.startedAt??new Date().toISOString()
  };
}

function draftFromQuiz(quiz=state.quiz){
  if(!quiz||!state.chapterData||quiz.chapterId!==state.chapterData.chapter.id||quiz.submitted) return null;
  return {
    chapterId:quiz.chapterId,
    questionIds:state.chapterData.questions.map(q=>q.id),
    answers:{...quiz.answers},
    index:quiz.index,
    startedAt:quiz.startedAt
  };
}

function persistQuizDraft(){
  const draft=draftFromQuiz();
  if(!draft) return;
  const progress=saveDraft(state.progress,draft.chapterId,draft);
  dispatch({type:"PROGRESS_UPDATED",progress},{renderNow:false});
  captureStorageNotice();
}

async function beginNewExam(chapterId,{confirmRestart=true}={}){
  const data=await ensureChapter(chapterId);
  if(!data) return;
  const existing=getDraft(state.progress,chapterId);
  if(existing&&confirmRestart){
    const ok=await confirmAction({
      title:"Start this exam over?",
      message:"Your saved in-progress answers for this chapter will be removed. Completed attempts will remain in your local history.",
      confirmLabel:"Start over",
      destructive:true
    });
    if(!ok) return;
  }
  const progress=existing?removeDraft(state.progress,chapterId):state.progress;
  if(progress!==state.progress){dispatch({type:"PROGRESS_UPDATED",progress},{renderNow:false});captureStorageNotice();}
  dispatch({type:"START_QUIZ",chapterId,index:0,answers:{},startedAt:new Date().toISOString()},{renderNow:false});
  persistQuizDraft();
  location.hash=`#/quiz/${chapterId}`;
}

async function resumeExam(chapterId){
  const data=await ensureChapter(chapterId);
  if(!data) return;
  const restored=compatibleDraft(data,getDraft(state.progress,chapterId));
  if(!restored){
    const progress=removeDraft(state.progress,chapterId);
    dispatch({type:"PROGRESS_UPDATED",progress},{renderNow:false});
    captureStorageNotice();
    await beginNewExam(chapterId,{confirmRestart:false});
    return;
  }
  dispatch({type:"START_QUIZ",...restored,resumed:true},{renderNow:false});
  location.hash=`#/quiz/${chapterId}`;
}

const actions={
  startExam:chapterId=>beginNewExam(chapterId),
  resumeExam,
  answer:(questionId,choiceId)=>{
    dispatch({type:"ANSWER",questionId,choiceId},{renderNow:false});
    persistQuizDraft();
    render({focusSelector:`input[data-question-id="${questionId}"][data-choice-id="${choiceId}"]`});
    announce("Answer selected and saved on this device.");
  },
  goTo:index=>{
    if(!state.chapterData||!state.quiz) return;
    const safeIndex=clamp(index,0,state.chapterData.questions.length-1);
    dispatch({type:"GO_TO_QUESTION",index:safeIndex},{renderNow:false});
    persistQuizDraft();
    render({focusSelector:"#question-heading",scrollToTop:true});
    announce(`Question ${state.chapterData.questions[safeIndex].sourceNumber}.`);
  },
  exitExam:()=>{
    if(!state.quiz) return;
    persistQuizDraft();
    location.hash=`#/chapter/${state.quiz.chapterId}`;
  },
  submit:async()=>{
    if(!state.chapterData||!state.quiz) return;
    const questions=state.chapterData.questions;
    const unanswered=questions.length-Object.keys(state.quiz.answers).length;
    const ok=await confirmAction({
      title:"Submit chapter exam?",
      message:unanswered?`${unanswered} question${unanswered===1?" is":"s are"} unanswered. Unanswered questions will be scored as incorrect. Submit now?`:`All ${questions.length} questions are answered. Submit to reveal the official answers and rationales?`,
      confirmLabel:"Submit exam"
    });
    if(!ok) return;
    const chapterId=state.quiz.chapterId;
    const attempt=createAttempt(questions,state.quiz.answers,{
      startedAt:state.quiz.startedAt,
      contentVersion:state.chapterData.contentVersion??null
    });
    const progress=saveAttempt(state.progress,chapterId,attempt);
    dispatch({type:"SUBMIT_QUIZ",result:attempt.score,attempt},{renderNow:false});
    dispatch({type:"PROGRESS_UPDATED",progress},{renderNow:false});
    captureStorageNotice();
    location.hash=`#/results/${chapterId}/${encodeURIComponent(attempt.id)}`;
    announce(`Chapter exam submitted. Score ${attempt.score.percentage} percent.`);
  },
  retake:chapterId=>beginNewExam(chapterId,{confirmRestart:false}),
  setReviewFilter:filter=>{
    const allowed=new Set(["all","correct","incorrect","unanswered"]);
    const safe=allowed.has(filter)?filter:"all";
    dispatch({type:"SET_REVIEW_FILTER",filter:safe},{focusSelector:"#review-heading"});
    announce(`Answer review filtered to ${safe}.`);
  },
  clearDraft:async chapterId=>{
    const draft=getDraft(state.progress,chapterId);
    if(!draft) return;
    const ok=await confirmAction({
      title:"Clear this unfinished attempt?",
      message:"This removes the saved answers and position for the current unfinished chapter attempt. Completed attempt history will remain.",
      confirmLabel:"Clear unfinished attempt",
      destructive:true
    });
    if(!ok) return;
    const progress=removeDraft(state.progress,chapterId);
    dispatch({type:"PROGRESS_UPDATED",progress},{renderNow:false});
    captureStorageNotice();render();
    announce("Unfinished chapter attempt cleared.");
  },
  deleteChapterHistory:async chapterId=>{
    const attempts=state.progress.chapters?.[chapterId]?.attempts??[];
    if(!attempts.length) return;
    const ok=await confirmAction({
      title:"Delete this chapter's history?",
      message:`This permanently removes ${attempts.length} completed attempt${attempts.length===1?"":"s"} for this chapter from the current browser. An unfinished attempt, if present, will remain.`,
      confirmLabel:"Delete chapter history",
      destructive:true
    });
    if(!ok) return;
    const progress=deleteChapterHistory(state.progress,chapterId);
    dispatch({type:"PROGRESS_UPDATED",progress},{renderNow:false});
    captureStorageNotice();render();
    announce("Completed chapter history deleted.");
  },
  exportProgress:()=>{
    try{
      downloadText(backupFilename(),serializeProgressBackup(state.progress,state.manifest));
      dispatch({type:"BACKUP_MESSAGE",message:{type:"success",text:"Backup downloaded. Keep the JSON file in a safe location."},clearPreview:false});
      announce("Progress backup downloaded.");
    }catch(error){
      dispatch({type:"BACKUP_MESSAGE",message:{type:"error",text:error.message||"The backup could not be created."},clearPreview:false});
      announce("Progress backup could not be created.");
    }
  },
  chooseImport:async file=>{
    dispatch({type:"BACKUP_MESSAGE",message:{type:"info",text:"Validating the selected backup…"},clearPreview:true});
    try{
      validateImportFileMeta(file);
      const value=parseBackupText(await file.text());
      const questionSets=await loadActiveQuestionSets();
      const preview=validateProgressBackup(value,{manifest:state.manifest,questionSets});
      dispatch({type:"IMPORT_PREVIEW",preview,message:{type:"success",text:"Backup validated. Review the summary before importing."}},{focusSelector:"#import-preview-heading"});
      announce("Backup validated and ready for review.");
    }catch(error){
      dispatch({type:"IMPORT_PREVIEW",preview:null,message:{type:"error",text:error.message||"The selected backup could not be validated."}},{focusSelector:"#backup-heading"});
      announce("Backup validation failed.");
    }
  },
  cancelImport:()=>{
    dispatch({type:"IMPORT_PREVIEW",preview:null,message:{type:"info",text:"Import cancelled. Existing progress was not changed."}},{focusSelector:"#backup-file"});
    announce("Import cancelled.");
  },
  confirmImport:async()=>{
    const preview=state.importPreview;if(!preview) return;
    const current=state.progress;
    const currentSummary=state.manifest?state.manifest.chapters.reduce((count,chapter)=>count+(current.chapters?.[chapter.id]?.attempts?.length??0),0):0;
    const ok=await confirmAction({
      title:"Replace local progress with this backup?",
      message:`This backup contains ${preview.summary.attempts} completed attempt${preview.summary.attempts===1?"":"s"} and ${preview.summary.drafts} unfinished attempt${preview.summary.drafts===1?"":"s"}. It will replace the ${currentSummary} completed attempt${currentSummary===1?"":"s"} currently stored in this browser. This action cannot be undone unless you export the current record first.`,
      confirmLabel:"Import and replace",
      destructive:true
    });
    if(!ok) return;
    const progress=replaceProgress(preview.progress);
    const status=captureStorageNotice();
    if(!status.ok){
      dispatch({type:"BACKUP_MESSAGE",message:{type:"error",text:status.message},clearPreview:false});
      announce("Import could not be saved.");return;
    }
    dispatch({type:"RESET",progress},{renderNow:false});
    dispatch({type:"BACKUP_MESSAGE",message:{type:"success",text:"Backup imported successfully. The restored progress is now active on this device."},clearPreview:true});
    render({focusSelector:"#backup-heading",scrollToTop:true});
    announce("Progress backup imported successfully.");
  },
  dismissNotice:()=>dispatch({type:"DISMISS_NOTICE"}),
  reset:async()=>{
    const ok=await confirmAction({
      title:"Reset all local progress?",
      message:"This permanently removes every in-progress exam and completed attempt saved by this application in the current browser.",
      confirmLabel:"Reset all progress",
      destructive:true
    });
    if(!ok) return;
    const progress=clearProgress();
    dispatch({type:"RESET",progress},{renderNow:false});
    captureStorageNotice();
    announce("All local progress reset.");
    location.hash="#/";
  }
};

async function handleRoute(route){
  dispatch({type:"NAVIGATE",route},{renderNow:false});
  if(["quiz","results"].includes(route.name)){
    const ch=chapterConfig(route.chapterId);
    if(!ch||ch.status!=="available"||!ch.data){
      location.hash=`#/chapter/${route.chapterId}`;
      return;
    }
    try{
      const data=await ensureChapter(route.chapterId);
      if(route.name==="quiz"){
        const sameActive=state.quiz?.chapterId===route.chapterId&&!state.quiz.submitted;
        if(!sameActive){
          const restored=compatibleDraft(data,getDraft(state.progress,route.chapterId));
          if(restored) dispatch({type:"START_QUIZ",...restored,resumed:true},{renderNow:false});
          else{
            dispatch({type:"START_QUIZ",chapterId:route.chapterId,index:0,answers:{},startedAt:new Date().toISOString()},{renderNow:false});
            persistQuizDraft();
          }
        }
      }else{
        const attempt=getAttempt(state.progress,route.chapterId,route.attemptId);
        if(!attempt){
          location.hash=`#/chapter/${route.chapterId}`;
          return;
        }
        const sameResult=state.quiz?.chapterId===route.chapterId&&state.quiz.submitted&&state.quiz.attempt?.id===attempt.id;
        if(!sameResult){
          dispatch({type:"RESTORE_RESULT",chapterId:route.chapterId,attempt,result:scoreAttempt(data.questions,attempt.answers)},{renderNow:false});
        }
      }
    }catch(error){
      dispatch({type:"ERROR",error},{renderNow:false});
    }
  }
  const isInitial=!hasHandledInitialRoute;
  hasHandledInitialRoute=true;
  render({focusSelector:isInitial?null:"#app h1",scrollToTop:!isInitial});
}

async function main(){
  try{
    const manifest=await loadManifest();
    const progress=readProgress();
    const storageStatus=getStorageStatus();
    const notice=!storageStatus.ok||storageStatus.recovered?{type:storageStatus.ok?"warning":"error",text:storageStatus.message}:null;
    state=initialState(manifest,progress,{notice});
    setupMenu();
    startRouter(handleRoute);
  }catch(error){
    state={manifest:{chapters:[]},progress:{chapters:{}},route:{name:"home"},reviewFilter:"all",error};
    render({focusSelector:"#app h1",scrollToTop:true});
  }
}

function setupMenu(){
  const button=document.getElementById("menu-button");
  const nav=document.getElementById("primary-nav");
  const desktopQuery=window.matchMedia("(min-width:48rem)");
  const closeMenu=({returnFocus=false}={})=>{
    button.setAttribute("aria-expanded","false");
    button.setAttribute("aria-label","Open navigation menu");
    nav.classList.remove("open");
    document.body.classList.remove("nav-open");
    if(returnFocus) button.focus();
  };
  const openMenu=()=>{
    button.setAttribute("aria-expanded","true");
    button.setAttribute("aria-label","Close navigation menu");
    nav.classList.add("open");
    document.body.classList.add("nav-open");
    nav.querySelector("a")?.focus();
  };
  button.addEventListener("click",()=>button.getAttribute("aria-expanded")==="true"?closeMenu({returnFocus:true}):openMenu());
  nav.addEventListener("click",()=>closeMenu());
  document.addEventListener("pointerdown",event=>{
    if(button.getAttribute("aria-expanded")!=="true") return;
    if(!nav.contains(event.target)&&!button.contains(event.target)) closeMenu();
  });
  document.addEventListener("keydown",event=>{
    if(event.key==="Escape"&&button.getAttribute("aria-expanded")==="true") closeMenu({returnFocus:true});
  });
  desktopQuery.addEventListener?.("change",event=>{if(event.matches) closeMenu();});
}

main();
